using System.Runtime.InteropServices;using System.Text;using System.Text.Json;namespace RVZSharp.Cli.Logging;internal sealed class BugReportApiClient : IDisposable{    private readonly HttpClient _httpClient;    private readonly string _applicationName;    private readonly string _version;    private static readonly JsonSerializerOptions JsonOptions = new()    {        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,        WriteIndented = false    };    public BugReportApiClient(string applicationName, string version)    {        _httpClient = new HttpClient();        _httpClient.DefaultRequestHeaders.Add("X-API-KEY", "hjh7yu6t56tyr540o9u8767676r5674534453235264c75b6t7ggghgg76trf564e");        _applicationName = applicationName;        _version = version;    }    public async Task SendBugReportAsync(string errorMessage, string? stackTrace = null)    {        try        {            var envDetails = BuildEnvironmentDetails();            var message = $"""                === Environment Details ===                {envDetails}                === Error Details ===                {errorMessage}                """;            var payload = new            {                message,                applicationName = _applicationName,                version = _version,                environment = RuntimeInformation.OSDescription,                stackTrace            };            var json = JsonSerializer.Serialize(payload, JsonOptions);            using var content = new StringContent(json, Encoding.UTF8, "application/json");            var response = await _httpClient.PostAsync(                "https://www.purelogiccode.com/bugreport/api/send-bug-report", content).ConfigureAwait(false);            if (!response.IsSuccessStatusCode)            {                System.Diagnostics.Debug.WriteLine($"Bug report API returned {response.StatusCode}");            }        }        catch (Exception ex)        {            System.Diagnostics.Debug.WriteLine($"Failed to send bug report: {ex.Message}");        }    }    private static string BuildEnvironmentDetails()    {        return $"""            Date: {DateTime.Now:yyyy-MM-dd HH:mm:ss}            Application Name: {AppDomain.CurrentDomain.FriendlyName}            Application Version: {Environment.Version}            OS Version: {RuntimeInformation.OSDescription}            Architecture: {RuntimeInformation.ProcessArchitecture}            Bitness: {(Environment.Is64BitProcess ? 64 : 32)}            Windows Version: {Environment.OSVersion}            Processor Count: {Environment.ProcessorCount}            Base Directory: {AppDomain.CurrentDomain.BaseDirectory}            Temp Path: {Path.GetTempPath()}            """;    }    public void Dispose()    {        _httpClient.Dispose();    }}